/* From Uiverse.io by SharpTH - Tags: button */
.__UIV_SCOPE__ .draw-border {
 box-shadow: inset 0 0 0 4px #58afd1;
 color: #58afd1;
 transition: color 0.25s 0.0833333333s;
 position: relative;
}

.__UIV_SCOPE__ .draw-border::before, .__UIV_SCOPE__ .draw-border::after {
 border: 0 solid transparent;
 box-sizing: border-box;
 content: "";
 pointer-events: none;
 position: absolute;
 width: 0;
 height: 0;
 bottom: 0;
 right: 0;
}

.__UIV_SCOPE__ .draw-border::before {
 border-bottom-width: 4px;
 border-left-width: 4px;
}

.__UIV_SCOPE__ .draw-border::after {
 border-top-width: 4px;
 border-right-width: 4px;
}

.__UIV_SCOPE__ .draw-border:hover {
 color: #ffe593;
}

.__UIV_SCOPE__ .draw-border:hover::before, .__UIV_SCOPE__ .draw-border:hover::after {
 border-color: #ffe593;
 transition: border-color 0s, width 0.25s, height 0.25s;
 width: 100%;
 height: 100%;
}

.__UIV_SCOPE__ .draw-border:hover::before {
 transition-delay: 0s, 0s, 0.25s;
}

.__UIV_SCOPE__ .draw-border:hover::after {
 transition-delay: 0s, 0.25s, 0s;
}

.__UIV_SCOPE__ .btn {
 background: none;
 border: none;
 cursor: pointer;
 line-height: 1.5;
 font: 700 17px "Roboto Slab", sans-serif;
 padding: 1em 2em;
 letter-spacing: 0.05rem;
}

.__UIV_SCOPE__ .btn:focus {
 outline: 2px dotted #55d7dc;
}
